html:
{%- set letter_head = frappe.get_doc("Letter Head", "Main-LetterHead") -%}

<!-- Letter Head Header -->
{% if letter_head and letter_head.content %}
<div class="letter-head-header">
	{{ letter_head.content }}
</div>
{% endif %}

<style>
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    .print-format {
        font-family: Arial, sans-serif;
        color: #000;
        line-height: 1.3;
        max-width: 210mm;
        margin: 0 auto;
        background: white;
        padding:0!important;
    }

    .letter-head-header {
        margin-bottom: 0px;
    }

    .letter-head-footer {
        margin-top: 0px;
        position:fixed;
        bottom:0px;
        align-self:center;
        margin-top:20px;
    }

    /* Page container */
    .page {
        width: 210mm;
        min-height: 297mm;
        padding: 8mm 10mm;
        position: relative;
        display: flex;
        flex-direction: column;
    }

    .page-content {
        flex: 1;
    }

    /* Header Section */
    .gold-header {
        background: white;
        border: 2px solid #B8860B;
        padding: 8px 12px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 8px;
    }

    .header-left {
        color: #000;
        flex: 1;
    }

    .company-name {
        font-size: 14px;
        font-weight: bold;
        margin-bottom: 2px;
        text-transform: uppercase;
    }

    .company-address {
        font-size: 9px;
        line-height: 1.3;
    }

    .header-logo {
        width: 120px;
        height: 60px;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .header-logo img {
        max-width: 100%;
        max-height: 60px;
    }

    /* Document Title */
    .document-title {
        text-align: center;
        font-size: 16px;
        font-weight: bold;
        margin: 8px 0;
        text-transform: uppercase;
    }

    /* Contract Header Row */
    .contract-header {
        border: 1px solid #000;
        display: flex;
        margin-bottom: 6px;
    }

    .contract-header-item {
        padding: 5px 10px;
        flex: 1;
        display: flex;
        justify-content: space-between;
        border-right: 1px solid #000;
        font-size: 10px;
    }

    .contract-header-item:last-child {
        border-right: none;
    }

    .header-label {
        font-weight: bold;
    }

    /* Two Column Layout */
    .two-column-container {
        display: flex;
        gap: 6px;
        margin-bottom: 6px;
    }

    .left-column, .right-column {
        flex: 1;
        border: 1px solid #000;
    }

    /* Section Boxes */
    .section-box {
        border: 1px solid #000;
        margin-bottom: 6px;
    }

    .section-header {
        background: #e8e8e8;
        padding: 4px 8px;
        font-weight: bold;
        font-size: 10px;
        text-transform: uppercase;
        border-bottom: 1px solid #000;
    }

    .section-content {
        padding: 6px 10px;
    }

    .info-row {
        display: flex;
        margin-bottom: 3px;
        font-size: 10px;
    }

    .info-label {
        font-weight: bold;
        min-width: 85px;
    }

    .info-value {
        flex: 1;
    }

    /* Compact info grid */
    .info-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 3px 12px;
    }

    .info-grid-3 {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 3px 12px;
    }

    .info-grid-4 {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr 1fr;
        gap: 3px 10px;
    }

    /* Status Badge */
    .status-badge {
        display: inline-block;
        padding: 2px 8px;
        border-radius: 3px;
        font-size: 9px;
        font-weight: bold;
    }

    .status-active {
        background: #d4edda;
        color: #155724;
    }

    .status-completed {
        background: #cce5ff;
        color: #004085;
    }

    .status-cancelled {
        background: #f8d7da;
        color: #721c24;
    }

    /* Signature Section */
    .signature-section {
        display: flex;
        justify-content: space-between;
        gap: 15px;
        margin-top: auto;
        padding-top: 10px;
    }

    .signature-box {
        flex: 1;
        text-align: center;
        padding: 8px;
        border: 1px solid #000;
    }

    .signature-line {
        border-top: 1px solid #000;
        margin: 40px 15px 8px 15px;
    }

    .signature-label {
        font-size: 9px;
        font-weight: bold;
    }

    .signature-name {
        font-size: 9px;
        margin-top: 3px;
    }

    /* Footer */
    .page-footer {
        text-align: center;
        font-size: 9px;
        padding-top: 5px;
        border-top: 1px solid #ccc;
        margin-top: 5px;
    }

    /* Print styles */
    @media print {
        .page {
            page-break-after: avoid;
            break-after: avoid;
        }
        body {
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
        }
    }

    @page {
        size: A4;
        margin: 0;
    }
</style>

<div class="print-format">
    <div class="page">
        <div class="page-content">
            <!-- Title -->
            <div class="document-title">Non-Revenue Movement Agreement</div>

            <!-- NRM Header -->
            <div class="contract-header">
                <div class="contract-header-item">
                    <span class="header-label">NRM No:</span>
                    <span>{{ doc.name }}</span>
                </div>
                <div class="contract-header-item">
                    <span class="header-label">Movement Type:</span>
                    <span>{{ doc.movement_type or "-" }}</span>
                </div>
                <div class="contract-header-item">
                    <span class="header-label">Total Days:</span>
                    <span>{{ doc.total_days or 0 }}</span>
                </div>
                <div class="contract-header-item">
                    <span class="header-label">Status:</span>
                    <span class="status-badge {% if doc.status == 'Active' %}status-active{% elif doc.status == 'Completed' %}status-completed{% else %}status-cancelled{% endif %}">{{ doc.status or "Active" }}</span>
                </div>
            </div>

            <!-- Vehicle Details -->
            <div class="section-box">
                <div class="section-header">Vehicle Details</div>
                <div class="section-content">
                    <div class="info-grid-3">
                        <div class="info-row">
                            <div class="info-label">Vehicle:</div>
                            <div class="info-value">{{ doc.vehicle or "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Plate No:</div>
                            <div class="info-value">{{ doc.vehicle_plate or "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Make/Model:</div>
                            <div class="info-value">{{ doc.make_and_model or "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Vehicle Type:</div>
                            <div class="info-value">{{ doc.vehicle_type or "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Body Type:</div>
                            <div class="info-value">{{ doc.body_type or "-" }}</div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Assigned To Details -->
            <div class="section-box">
                <div class="section-header">Assigned To</div>
                <div class="section-content">
                    <div class="info-grid">
                        <div class="info-row">
                            <div class="info-label">Assigned To:</div>
                            <div class="info-value">{{ doc.assigned_to_type or "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Name:</div>
                            <div class="info-value">{{ doc.assigned_person_name or "-" }}</div>
                        </div>
                        {% if doc.staff %}
                        <div class="info-row">
                            <div class="info-label">Staff:</div>
                            <div class="info-value">{{ doc.staff }}</div>
                        </div>
                        {% endif %}
                        {% if doc.staff_code %}
                        <div class="info-row">
                            <div class="info-label">Staff Code:</div>
                            <div class="info-value">{{ doc.staff_code }}</div>
                        </div>
                        {% endif %}
                        {% if doc.driver %}
                        <div class="info-row">
                            <div class="info-label">Driver:</div>
                            <div class="info-value">{{ doc.driver }}</div>
                        </div>
                        {% endif %}
                        {% if doc.customer %}
                        <div class="info-row">
                            <div class="info-label">Customer:</div>
                            <div class="info-value">{{ doc.customer }}</div>
                        </div>
                        {% endif %}
                        {% if doc.other_name %}
                        <div class="info-row">
                            <div class="info-label">Other:</div>
                            <div class="info-value">{{ doc.other_name }}</div>
                        </div>
                        {% endif %}
                        <div class="info-row">
                            <div class="info-label">Contact:</div>
                            <div class="info-value">{{ doc.contact_number or "-" }}</div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- OUT/IN Details -->
            <div class="two-column-container">
                <div class="left-column">
                    <div class="section-header">OUT Details</div>
                    <div class="section-content">
                        <div class="info-row">
                            <div class="info-label">Date/Time:</div>
                            <div class="info-value">{{ frappe.utils.format_datetime(doc.date_out, "dd-MMM-yy HH:mm") if doc.date_out else "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Odometer:</div>
                            <div class="info-value">{{ "{:,}".format(doc.odometer_out|int) if doc.odometer_out else "-" }} KM</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Fuel Level:</div>
                            <div class="info-value">{{ doc.fuel_level_out or "-" }}</div>
                        </div>
                    </div>
                </div>
                <div class="right-column">
                    <div class="section-header">IN Details</div>
                    <div class="section-content">
                        <div class="info-row">
                            <div class="info-label">Date/Time:</div>
                            <div class="info-value">{{ frappe.utils.format_datetime(doc.date_in, "dd-MMM-yy HH:mm") if doc.date_in else "-" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Odometer:</div>
                            <div class="info-value">{{ "{:,}".format(doc.odometer_in|int) if doc.odometer_in else "-" }} KM</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">Fuel Level:</div>
                            <div class="info-value">{{ doc.fuel_level_in or "-" }}</div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- KM Summary -->
            <div class="section-box">
                <div class="section-header">Mileage Summary</div>
                <div class="section-content">
                    <div class="info-grid-3">
                        <div class="info-row">
                            <div class="info-label">KM Out:</div>
                            <div class="info-value">{{ "{:,}".format(doc.odometer_out|int) if doc.odometer_out else "0" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label">KM In:</div>
                            <div class="info-value">{{ "{:,}".format(doc.odometer_in|int) if doc.odometer_in else "0" }}</div>
                        </div>
                        <div class="info-row">
                            <div class="info-label" style="font-weight: bold;">KM Travelled:</div>
                            <div class="info-value" style="font-weight: bold;">{{ "{:,}".format(doc.km_travelled|int) if doc.km_travelled else "0" }}</div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Purpose & Remarks -->
            {% if doc.purpose or doc.remarks %}
            <div class="section-box">
                <div class="section-header">Purpose & Remarks</div>
                <div class="section-content" style="font-size: 9px;">
                    {% if doc.purpose %}
                    <div class="info-row">
                        <div class="info-label">Purpose:</div>
                        <div class="info-value">{{ doc.purpose }}</div>
                    </div>
                    {% endif %}
                    {% if doc.remarks %}
                    <div class="info-row">
                        <div class="info-label">Remarks:</div>
                        <div class="info-value">{{ doc.remarks }}</div>
                    </div>
                    {% endif %}
                </div>
            </div>
            {% endif %}
        </div>

        <!-- Signatures -->
        <div class="signature-section">
            <div class="signature-box">
                <div class="signature-line"></div>
                <div class="signature-label">Authorized By</div>
                <div class="signature-name">{{ frappe.db.get_default("company") or "RIGHT HIRE" }}</div>
            </div>
            <div class="signature-box">
                <div class="signature-line"></div>
                <div class="signature-label">Received By</div>
                <div class="signature-name">{{ doc.assigned_person_name or "" }}</div>
            </div>
        </div>
    </div>
</div>

<!-- Letter Head Footer -->
{% if letter_head and letter_head.footer %}
<div class="letter-head-footer">
	{{ letter_head.footer }}
</div>
{% endif %}
